Sure! Here's some Go code that should accomplish what you're looking for:
```go
package main
import (
	"fmt"
	"math/rand"
	"time"
)
func main() {
	verbs := []string{"Shake", "Dance", "Move", "Groove", "Jump", "Bounce"}
	nouns := []string{"Body", "Beat", "Rhythm", "Floor", "Party", "Feet"}
	// Seed the random number generator
	rand.Seed(time.Now().Unix())
	// Generate 10 song titles
	numTitles := 10
	titles := make([]string, numTitles)
	for i := 0; i < numTitles; i++ {
		verb := verbs[rand.Intn(len(verbs))]
		noun := nouns[rand.Intn(len(nouns))]
