function shortestRoute($cities) {
  $n = count($cities);
  $visited = array_fill(0, $n, false);
  $path = array_fill(0, $n, 0);
  $minPath = PHP_INT_MAX;

  function calculateDistance($city1, $city2) {
    $distance = 0;
    for ($i = 0; $i < strlen($city1); $i++) {
      $distance += ord($city1[$i]);
    }
    for ($i = 0; $i < strlen($city2); $i++) {
      $distance += ord($city2[$i]);
    }
    return $distance;
  }

  function findShortestPath($cities, $visited, $path, $currentLength, $currentIndex, &$minPath) {
    if ($currentIndex == $n) {
      $minPath = min($minPath, $currentLength);
      return;
    }
    for ($i = 0; $i < $n; $i++) {
      if (!$visited[$i]) {
        $visited[$i] = true;
        $path[$currentIndex] = $i;
        if ($currentIndex == 0) {
          findShortestPath($cities, $visited, $path, 0, $currentIndex + 1, $minPath);
        } else {
          $distance = calculateDistance($cities[$path[$currentIndex - 1]], $cities[$i]);
          findShortestPath($cities, $visited, $path, $currentLength + $distance, $currentIndex + 1, $minPath);
        }
        $visited[$i] = false;
      }
    }
  }

  findShortestPath($cities, $visited, $path, 0, 0, $minPath);
  return $minPath;
}
