    static void Main(string[] args)
    {
        double[,] matrix = {{2, 3, -4, 15},
                            {3, -4, 2, -4},
                            {5, 6, -3, 14}};
        int n = 3;
        for (int i = 0; i < n; i++)
        {
            double max = Math.Abs(matrix[i, i]);
            int maxRow = i;
            for (int j = i + 1; j < n; j++)
            {
                if (Math.Abs(matrix[j, i]) > max)
                {
                    max = Math.Abs(matrix[j, i]);
                    maxRow = j;
                }
            }
            for (int j = i; j < n + 1; j++)
            {
                double temp = matrix[maxRow, j];
                matrix[maxRow, j] = matrix[i, j];
                matrix[i, j] = temp;
            }
            for (int j = i + 1; j < n; j++)
            {
                double c = -matrix[j, i] / matrix[i, i];
                for (int k = i; k < n + 1; k++)
                {
                    if (i == k)
                    {
                        matrix[j, k] = 0;
                    }
                    else
                    {
                        matrix[j, k] += c * matrix[i, k];
                    }
                }
            }
        }
        double[] solution = new double[n];
        for (int i = n - 1; i >= 0; i--)
        {
            solution[i] = matrix[i, n] / matrix[i, i];
            for (int j = i - 1; j >= 0; j--)
            {
                matrix[j, n] -= matrix[j, i] * solution[i];
            }
        }
