To programmatically retrieve the specifications of a laptop computer using C# code, you can use the ManagementObjectSearcher class in the System.Management namespace. Here's an example code snippet that retrieves the specifications of the laptop's CPU, GPU, RAM, and storage:
```csharp
using System;
using System.Management;
public static void GetLaptopSpecs()
{
    ManagementObjectSearcher searcher;
    // Retrieve CPU information
    searcher = new ManagementObjectSearcher("select * from Win32_Processor");
    foreach (ManagementObject obj in searcher.Get())
    {
        Console.WriteLine("CPU: " + obj["Name"]);
        Console.WriteLine("Number of cores: " + obj["NumberOfCores"]);
        Console.WriteLine("Clock speed: " + obj["MaxClockSpeed"] + " MHz");
    }
    // Retrieve GPU information
    searcher = new ManagementObjectSearcher("select * from Win32_VideoController");
    foreach (ManagementObject obj in searcher.Get())
    {
        Console.WriteLine("GPU: " + obj["Name"]);
        Console.WriteLine("Video memory: " + obj["AdapterRAM"] + " bytes");
    }
    // Retrieve RAM information
    searcher = new ManagementObjectSearcher("select * from Win32_PhysicalMemory");
    long totalMemory = 0;
    foreach (ManagementObject obj in searcher.Get())
    {
        totalMemory += Convert.ToInt64(obj["Capacity"]);
    }
    Console.WriteLine("Total RAM: " + totalMemory / (1024 * 1024) + " MB");
    // Retrieve storage information
    searcher = new ManagementObjectSearcher("select * from Win32_DiskDrive");
    foreach (ManagementObject obj in searcher.Get())
    {
        Console.WriteLine("Storage: " + obj["Caption"]);
        Console.WriteLine("Capacity: " + obj["Size"] + " bytes");
    }
}
```
