import java.util.Random;
public class SynestheticSunset {
    public static void main(String[] args) {
        String[] colors = {"fiery red", "burnt orange", "golden yellow", "deep purple", "bright pink"};
        String[] tastes = {"sweet", "sour", "bitter", "savory", "spicy"};
        String[] textures = {"smooth", "crunchy", "fluffy", "gooey", "gritty"};
        String[] sounds = {"whispering", "rustling", "chirping", "crackling", "roaring"};
        Random rand = new Random();
        int colorIndex = rand.nextInt(colors.length);
        int tasteIndex = rand.nextInt(tastes.length);
