To incorporate blockchain technology and ensure data integrity, we can modify the code to include the following steps:
1. Create a unique identifier for each data entry using a hashing algorithm.
2. Store the hash of the data entry along with the data in a block on the blockchain.
3. Use consensus mechanisms to ensure that the block is validated by multiple nodes on the network before it is added to the blockchain.
4. Use cryptography to ensure that the data is encrypted and only accessible to authorized parties.
5. Implement smart contracts to automate data management processes and ensure that they are executed according to predefined rules and conditions.
Here's an example of how this modified code could look like:
#include <iostream>
#include <string>
#include <vector>
#include <openssl/sha.h>
using namespace std;
struct Block {
    int data;
    string hash;
    string prevHash;
};
vector<Block> blockchain;
string calculateHash(int data, string prevHash) {
    string input = to_string(data) + prevHash;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)input.c_str(), input.length(), hash);
    string output = "";
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        output += hash[i];
    }
    return output;
}
void addBlock(int data) {
    Block newBlock;
    newBlock.data = data;
    newBlock.prevHash = blockchain[blockchain.size()-1].hash;
    newBlock.hash = calculateHash(data, newBlock.prevHash);
    blockchain.push_back(newBlock);
}
int main() {
