    public static void main(String[] args) {
        Random rand = new Random();
        String[] adjectives = new String[10];
        for (int i = 0; i < 10; i++) {
            int category = rand.nextInt(3);
            switch (category) {
                case 0:
                    adjectives[i] = APPEARANCE_ADJECTIVES[rand.nextInt(APPEARANCE_ADJECTIVES.length)];
                    break;
                case 1:
                    adjectives[i] = SCENT_ADJECTIVES[rand.nextInt(SCENT_ADJECTIVES.length)];
                    break;
                case 2:
                    adjectives[i] = SYMBOLIC_ADJECTIVES[rand.nextInt(SYMBOLIC_ADJECTIVES.length)];
                    break;
            }
        }
        System.out.println("Ten adjectives to describe a red rose:");
        for (String adjective : adjectives) {
            System.out.println(adjective);
        }
    }
}
