#include <vector>
#include <algorithm>
using namespace std;
// Define a function to analyze the frequency of characters in a string
vector<pair<char, int>> analyzeFrequency(string text) {
    vector<pair<char, int>> frequency;
    for (char c = 'a'; c <= 'z'; c++) {
        int count = count(text.begin(), text.end(), c);
        frequency.push_back(make_pair(c, count));
    }
    sort(frequency.begin(), frequency.end(), [](pair<char, int> a, pair<char, int> b) {
        return a.second > b.second;
    });
    return frequency;
}
