import org.apache.commons.math3.linear.ArrayRealVector;
import org.apache.commons.math3.linear.LUDecomposition;
import org.apache.commons.math3.stat.regression.LogisticRegression;
public class PurchasePrediction {
    public static void main(String[] args) {
        // Input data
        double[][] input = {
            {1, 0, 1}, // customer 1: inquired about cost and availability
            {0, 1, 0}, // customer 2: only inquired about availability
            {1, 1, 1}, // customer 3: inquired about both cost and availability
            {0, 0, 1}, // customer 4: only inquired about cost
        };
        // Output data (1 = purchased, 0 = did not purchase)
        double[] output = {1, 0, 1, 0};
        // Create a matrix from the input data
        RealMatrix matrix = new Array2DRowRealMatrix(input);
        // Create a vector from the output data
        RealVector vector = new ArrayRealVector(output);
        // Fit the logistic regression model to the data
        LogisticRegression lr = new LogisticRegression();
        lr.fit(matrix, vector);
        // Predict the likelihood of a new customer making a purchase
        double[] newCustomer = {1, 1, 0}; // inquired about cost but not availability
